const xml = $input.first().json.data || $input.first().json.body || $input.first().json;
const text = typeof xml === 'string' ? xml : JSON.stringify(xml);

// Estrae le entry del feed Atom YouTube
const entries = [];
const entryRegex = /<entry>([\s\S]*?)<\/entry>/g;
let match;
while ((match = entryRegex.exec(text)) !== null) {
  const block = match[1];
  const get = (tag) => {
    const m = block.match(new RegExp(`<${tag}[^>]*>([\\s\\S]*?)<\\/${tag}>`));
    return m ? m[1].trim() : '';
  };
  const getAttr = (tag, attr) => {
    const m = block.match(new RegExp(`<${tag}[^>]*${attr}=["']([^"']+)["']`));
    return m ? m[1] : '';
  };

  const videoId = getAttr('yt:videoId', '') || get('yt:videoId') || getAttr('id', '').split(':').pop();
  const title = get('title').replace(/<!\[CDATA\[|\]\]>/g, '').trim();
  const link = getAttr('link', 'href') || `https://www.youtube.com/watch?v=${videoId}`;
  const published = get('published') || get('updated');

  if (videoId && title) {
    entries.push({
      videoId,
      title,
      link,
      published,
      id: videoId
    });
  }
}

entries.sort((a, b) => new Date(b.published) - new Date(a.published));
return entries.slice(0, 3).map(e => ({ json: e }));

const fs = require('fs');
const path = require('path');

const OUTPUT_DIR = 'C:\\percorso\\auto-clipper\\output';
const PUBLISHED_DIR = path.join(OUTPUT_DIR, 'published');

if (!fs.existsSync(PUBLISHED_DIR)) {
  fs.mkdirSync(PUBLISHED_DIR, { recursive: true });
}

const files = fs.readdirSync(OUTPUT_DIR).filter(f => f.endsWith('.meta.json'));
const items = [];

for (const metaFile of files) {
  const metaPath = path.join(OUTPUT_DIR, metaFile);
  const meta = JSON.parse(fs.readFileSync(metaPath, 'utf8'));
  const mp4Name = path.basename(meta.video_path || metaFile.replace('.meta.json', '.mp4'));
  const mp4Path = path.join(OUTPUT_DIR, mp4Name);

  if (!fs.existsSync(mp4Path)) continue;
  if (fs.existsSync(path.join(PUBLISHED_DIR, mp4Name))) continue;

  items.push({
    json: {
      metaPath,
      mp4Path,
      title: meta.title,
      caption: meta.caption || meta.social_caption || '',
      hashtags: (meta.hashtags || []).join(' '),
      platforms: meta.platforms || meta.recommended_platforms || [],
      viral_score: meta.viral_score,
      videoId: meta.source?.video_id || '',
      fullCaption: `${meta.caption || meta.social_caption || ''} ${(meta.hashtags || []).join(' ')}`.trim()
    }
  });
}

return items;
